#!/usr/bin/env bash
# step92 — Phase 4b: customer trial claim flow. Adds routes/trials.js (/trials,
# /trials/claim, /account/trials), the pages, the trial_ready template, mounts
# the router, and refreshes the dashboard card. Graceful before the bot
# generate-trial endpoint exists. Idempotent; rolls back server.js + dashboard.
set -euo pipefail
APP=/opt/gsz
TS=$(date +%Y%m%d-%H%M%S)
BAK=$APP/.bak-step92-$TS
mkdir -p "$BAK/routes" "$BAK/views/account"
cp "$APP/server.js" "$BAK/server.js"
cp "$APP/views/account/dashboard.ejs" "$BAK/views/account/dashboard.ejs"
restore(){ echo "!! rollback"; cp "$BAK/server.js" "$APP/server.js"; cp "$BAK/views/account/dashboard.ejs" "$APP/views/account/dashboard.ejs"; rm -f "$APP/routes/trials.js" "$APP/views/trials.ejs" "$APP/views/account/trials.ejs"; pm2 restart gsz --update-env >/dev/null 2>&1 || true; }
trap 'restore' ERR
cd "$APP"

echo "==> seed trial_ready template"
node <<'NODE'
require('dotenv').config();
const { Pool } = require('pg');
const p = new Pool({ host:process.env.DB_HOST, port:process.env.DB_PORT, database:process.env.DB_NAME, user:process.env.DB_USER, password:process.env.DB_PASS });
(async()=>{
  await p.query("INSERT INTO wa_templates(key,body) VALUES('whatsapp.trial_ready','🎁 Your {{server_name}} free trial is ready ({{duration_label}}). View it here: {{secure_link}}') ON CONFLICT(key) DO NOTHING");
  console.log('   whatsapp.trial_ready ready');
  await p.end();
})().catch(e=>{ console.error('FAIL: '+e.message); process.exit(1); });
NODE

echo "==> write files"
base64 -d > "$APP/routes/trials.js" <<'B64'

B64
base64 -d > "$APP/views/trials.ejs" <<'B64'

B64
base64 -d > "$APP/views/account/trials.ejs" <<'B64'

B64
base64 -d > "$APP/views/account/dashboard.ejs" <<'B64'

B64

echo "==> patch server.js (mount trials router)"
node <<'NODE'
const fs=require('fs'); const f='/opt/gsz/server.js'; let s=fs.readFileSync(f,'utf8');
if(s.indexOf("routes/trials")>=0){ console.log('   server already'); }
else {
  const a="const whatsappRouter = require('./routes/whatsapp')(pool);\napp.use('/', whatsappRouter);";
  if(s.indexOf(a)<0){ console.error('!! whatsapp mount anchor not found'); process.exit(2); }
  s=s.replace(a, a+"\nconst trialsRouter = require('./routes/trials')(pool);\napp.use('/', trialsRouter);");
  fs.writeFileSync(f,s); console.log('   server patched');
}
NODE

echo "==> node --check + ejs compile + restart"
node --check "$APP/routes/trials.js"; node --check "$APP/server.js"
node -e "const ejs=require('ejs'),fs=require('fs');['views/trials.ejs','views/account/trials.ejs','views/account/dashboard.ejs'].forEach(v=>{ejs.compile(fs.readFileSync('$APP/'+v,'utf8'),{filename:'$APP/'+v});});console.log('   views compile');"
pm2 restart gsz --update-env >/dev/null; sleep 3
grep -q '</html>' <<<"$(curl -s -m 15 http://127.0.0.1:3900/ || true)" || { echo "!! home broken"; false; }
grep -q '</html>' <<<"$(curl -s -m 12 http://127.0.0.1:3900/trials || true)" || { echo "!! /trials not rendering"; false; }
C1=$(curl -s -o /dev/null -w '%{http_code}' -m 10 http://127.0.0.1:3900/account/trials || true)
[ "$C1" = "302" ] || { echo "!! /account/trials should redirect when signed out (got $C1)"; false; }
trap - ERR
echo "==> step92 OK — trial claim flow live. Backup: $BAK"
echo "   Public: /trials  |  Customer: /account/trials  |  Gated on verified account + LID quota."
